export default [{"id":"1161","jozz":"9","page":"177","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"3","line_end":"5","aya_no":"1","aya_text":"يَسۡـَٔلُونَكَ عَنِ ٱلۡأَنفَالِۖ قُلِ ٱلۡأَنفَالُ لِلَّهِ وَٱلرَّسُولِۖ فَٱتَّقُواْ ٱللَّهَ وَأَصۡلِحُواْ ذَاتَ بَيۡنِكُمۡۖ وَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥٓ إِن كُنتُم مُّؤۡمِنِينَ","aya_text_emlaey":"يسألونك عن الأنفال قل الأنفال لله والرسول فاتقوا الله وأصلحوا ذات بينكم وأطيعوا الله ورسوله إن كنتم مؤمنين","aya_tafseer":"[1] يسألك أصحابك -أيها النبي- عن الغنائم يوم «بدر» كيف تقسمها بينهم؟ قل لهم: إنَّ أمرها إلى الله ورسوله، فالرسول يتولى قسمتها بأمر ربه، فاتقوا عقاب الله ولا تُقْدموا على معصيته، واتركوا المنازعة والمخاصمة بسبب هذه الأموال، وأصلحوا الحال بينكم، والتزموا طاعة الله ورسوله إن كنتم مؤمنين؛ فإن الإيمان يدعو إلى طاعة الله ورسوله."},{"id":"1162","jozz":"9","page":"177","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"5","line_end":"7","aya_no":"2","aya_text":"إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَإِذَا تُلِيَتۡ عَلَيۡهِمۡ ءَايَٰتُهُۥ زَادَتۡهُمۡ إِيمَٰنٗا وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ","aya_text_emlaey":"إنما المؤمنون الذين إذا ذكر الله وجلت قلوبهم وإذا تليت عليهم آياته زادتهم إيمانا وعلى ربهم يتوكلون","aya_tafseer":"[2] إنما المؤمنون بالله حقّاً هم الذين إذا ذُكِر الله فزعت قلوبهم، وإذا تليت عليهم آيات القرآن زادتهم إيماناً مع إيمانهم؛ لتدبرهم لمعانيه، وعلى الله تعالى يتوكلون، فلا يرجون غيره، ولا يرهبون سواه."},{"id":"1163","jozz":"9","page":"177","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"7","line_end":"8","aya_no":"3","aya_text":"ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ","aya_text_emlaey":"الذين يقيمون الصلاة ومما رزقناهم ينفقون","aya_tafseer":"[3] الذين يداومون على أداء الصلوات المفروضة في أوقاتها، ومما رزقناهم من الأموال ينفقون فيما أمرناهم به."},{"id":"1164","jozz":"9","page":"177","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"8","line_end":"9","aya_no":"4","aya_text":"أُوْلَٰٓئِكَ هُمُ ٱلۡمُؤۡمِنُونَ حَقّٗاۚ لَّهُمۡ دَرَجَٰتٌ عِندَ رَبِّهِمۡ وَمَغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ","aya_text_emlaey":"أولئك هم المؤمنون حقا لهم درجات عند ربهم ومغفرة ورزق كريم","aya_tafseer":"[4] هؤلاء الذين يفعلون هذه الأفعال هم المؤمنون حقّاً ظاهراً وباطناً بما أنزل الله عليهم، لهم منازل عالية عند الله، وعفو عن ذنوبهم، ورزق كريم، وهو الجنة."},{"id":"1165","jozz":"9","page":"177","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"9","line_end":"10","aya_no":"5","aya_text":"كَمَآ أَخۡرَجَكَ رَبُّكَ مِنۢ بَيۡتِكَ بِٱلۡحَقِّ وَإِنَّ فَرِيقٗا مِّنَ ٱلۡمُؤۡمِنِينَ لَكَٰرِهُونَ","aya_text_emlaey":"كما أخرجك ربك من بيتك بالحق وإن فريقا من المؤمنين لكارهون","aya_tafseer":"[5] كما أنكم لما اختلفتم في المغانم فانتزعها الله منكم، وجعلها إلى قَسْمه وقَسْم رسوله -صلى الله عليه وسلم-، كذلك أمرك ربك -أيها النبي- بالخروج من «المدينة» للقاء عِيْر قريش، وذلك بالوحي الذي أتاك به جبريل مع كراهة فريق من المؤمنين للخروج."},{"id":"1166","jozz":"9","page":"177","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"11","line_end":"12","aya_no":"6","aya_text":"يُجَٰدِلُونَكَ فِي ٱلۡحَقِّ بَعۡدَ مَا تَبَيَّنَ كَأَنَّمَا يُسَاقُونَ إِلَى ٱلۡمَوۡتِ وَهُمۡ يَنظُرُونَ","aya_text_emlaey":"يجادلونك في الحق بعد ما تبين كأنما يساقون إلى الموت وهم ينظرون","aya_tafseer":"[6] يجادلك -أيها النبي- فريق من المؤمنين في القتال مِن بعد ما تبيَّن لهم أن ذلك واقع، كأنهم يساقون إلى الموت، وهم ينظرون إليه عِياناً."},{"id":"1167","jozz":"9","page":"177","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"12","line_end":"14","aya_no":"7","aya_text":"وَإِذۡ يَعِدُكُمُ ٱللَّهُ إِحۡدَى ٱلطَّآئِفَتَيۡنِ أَنَّهَا لَكُمۡ وَتَوَدُّونَ أَنَّ غَيۡرَ ذَاتِ ٱلشَّوۡكَةِ تَكُونُ لَكُمۡ وَيُرِيدُ ٱللَّهُ أَن يُحِقَّ ٱلۡحَقَّ بِكَلِمَٰتِهِۦ وَيَقۡطَعَ دَابِرَ ٱلۡكَٰفِرِينَ","aya_text_emlaey":"وإذ يعدكم الله إحدى الطائفتين أنها لكم وتودون أن غير ذات الشوكة تكون لكم ويريد الله أن يحق الحق بكلماته ويقطع دابر الكافرين","aya_tafseer":"[7] واذكروا -أيها المجادلون- وَعْدَ الله لكم بالظَّفَر بإحدى الطائفتين: العير وما تحمله مِن أرزاق، أو النفير، وهو قتال الأعداء والانتصار عليهم، وأنتم تحبون الظَّفَر بالعير دون القتال، ويريد الله أن يحق الإسلام، ويُعْليه بأمره إياكم بقتال الكفار، ويستأصلَ الكافرين بالهلاك."},{"id":"1168","jozz":"9","page":"177","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"15","line_end":"15","aya_no":"8","aya_text":"لِيُحِقَّ ٱلۡحَقَّ وَيُبۡطِلَ ٱلۡبَٰطِلَ وَلَوۡ كَرِهَ ٱلۡمُجۡرِمُونَ","aya_text_emlaey":"ليحق الحق ويبطل الباطل ولو كره المجرمون","aya_tafseer":"[8] ليُعِزَّ الله الإسلام وأهله، ويُذْهِبَ الشرك وأهله، ولو كره المشركون ذلك."},{"id":"1169","jozz":"9","page":"178","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"1","line_end":"2","aya_no":"9","aya_text":"إِذۡ تَسۡتَغِيثُونَ رَبَّكُمۡ فَٱسۡتَجَابَ لَكُمۡ أَنِّي مُمِدُّكُم بِأَلۡفٖ مِّنَ ٱلۡمَلَٰٓئِكَةِ مُرۡدِفِينَ","aya_text_emlaey":"إذ تستغيثون ربكم فاستجاب لكم أني ممدكم بألف من الملائكة مردفين","aya_tafseer":"[9] اذكروا نعمة الله عليكم يوم «بدر» إذ تطلبون النصر على عدوكم، فاستجاب الله لدعائكم قائلاً: إني ممدُّكم بألف من الملائكة من السماء، يتبع بعضهم بعضاً."},{"id":"1170","jozz":"9","page":"178","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"2","line_end":"4","aya_no":"10","aya_text":"وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ وَلِتَطۡمَئِنَّ بِهِۦ قُلُوبُكُمۡۚ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ","aya_text_emlaey":"وما جعله الله إلا بشرى ولتطمئن به قلوبكم وما النصر إلا من عند الله إن الله عزيز حكيم","aya_tafseer":"[10] وما جعل الله ذلك الإمداد إلا بشارة لكم بالنصر، ولتسكن به قلوبكم، وتوقنوا بنصر الله لكم، وما النصر إلا مِن عند الله، لا بشدة بأسكم وقواكم. إن الله عزيز في ملكه، حكيم في تدبيره وشرعه."},{"id":"1171","jozz":"9","page":"178","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"4","line_end":"6","aya_no":"11","aya_text":"إِذۡ يُغَشِّيكُمُ ٱلنُّعَاسَ أَمَنَةٗ مِّنۡهُ وَيُنَزِّلُ عَلَيۡكُم مِّنَ ٱلسَّمَآءِ مَآءٗ لِّيُطَهِّرَكُم بِهِۦ وَيُذۡهِبَ عَنكُمۡ رِجۡزَ ٱلشَّيۡطَٰنِ وَلِيَرۡبِطَ عَلَىٰ قُلُوبِكُمۡ وَيُثَبِّتَ بِهِ ٱلۡأَقۡدَامَ","aya_text_emlaey":"إذ يغشيكم النعاس أمنة منه وينـزل عليكم من السماء ماء ليطهركم به ويذهب عنكم رجز الشيطان وليربط على قلوبكم ويثبت به الأقدام","aya_tafseer":"[11] إذ يُلْقي الله عليكم النعاس أماناً منه لكم مِن خوف عدوكم أن يغلبكم، وينزل عليكم مِن السحاب ماء طهوراً؛ ليطهركم به من الأحداث الظاهرة، ويزيل عنكم في الباطن وساوس الشيطان وخواطره، وليشدَّ على قلوبكم بالصبر عند القتال، ويثبت به أقدام المؤمنين بتلبيد الأرض الرملية بالمطر حتى لا تنزلق فيها الأقدام."},{"id":"1172","jozz":"9","page":"178","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"7","line_end":"9","aya_no":"12","aya_text":"إِذۡ يُوحِي رَبُّكَ إِلَى ٱلۡمَلَٰٓئِكَةِ أَنِّي مَعَكُمۡ فَثَبِّتُواْ ٱلَّذِينَ ءَامَنُواْۚ سَأُلۡقِي فِي قُلُوبِ ٱلَّذِينَ كَفَرُواْ ٱلرُّعۡبَ فَٱضۡرِبُواْ فَوۡقَ ٱلۡأَعۡنَاقِ وَٱضۡرِبُواْ مِنۡهُمۡ كُلَّ بَنَانٖ","aya_text_emlaey":"إذ يوحي ربك إلى الملائكة أني معكم فثبتوا الذين آمنوا سألقي في قلوب الذين كفروا الرعب فاضربوا فوق الأعناق واضربوا منهم كل بنان","aya_tafseer":"[12] إذ يوحي ربك -أيها النبي- إلى الملائكة الذين أمدَّ الله بهم المسلمين في غزوة «بدر» أني معكم أُعينكم وأنصركم، فقوُّوا عزائم الذين آمنوا، سألقي في قلوب الذين كفروا الخوف الشديد والذلة والصَّغَار، فاضربوا -أيها المؤمنون- رؤوس الكفار، واضربوا منهم كل طرف ومِفْصل."},{"id":"1173","jozz":"9","page":"178","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"9","line_end":"11","aya_no":"13","aya_text":"ذَٰلِكَ بِأَنَّهُمۡ شَآقُّواْ ٱللَّهَ وَرَسُولَهُۥۚ وَمَن يُشَاقِقِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ","aya_text_emlaey":"ذلك بأنهم شاقوا الله ورسوله ومن يشاقق الله ورسوله فإن الله شديد العقاب","aya_tafseer":"[13] ذلك الذي حدث للكفار مِن ضَرْب رؤوسهم وأعناقهم وأطرافهم؛ بسبب مخالفتهم لأمر الله ورسوله، ومَن يخالف أمر الله ورسوله، فإن الله شديد العقاب له في الدنيا والآخرة."},{"id":"1174","jozz":"9","page":"178","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"11","line_end":"12","aya_no":"14","aya_text":"ذَٰلِكُمۡ فَذُوقُوهُ وَأَنَّ لِلۡكَٰفِرِينَ عَذَابَ ٱلنَّارِ","aya_text_emlaey":"ذلكم فذوقوه وأن للكافرين عذاب النار","aya_tafseer":"[14] ذلكم العذاب الذي عجَّلته لكم -أيها الكافرون المخالفون لأوامر الله ورسوله في الدنيا- فذوقوه في الحياة الدنيا، ولكم في الآخرة عذاب النار."},{"id":"1175","jozz":"9","page":"178","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"12","line_end":"13","aya_no":"15","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُواْ زَحۡفٗا فَلَا تُوَلُّوهُمُ ٱلۡأَدۡبَارَ","aya_text_emlaey":"ياأيها الذين آمنوا إذا لقيتم الذين كفروا زحفا فلا تولوهم الأدبار","aya_tafseer":"[15] يا أيها الذين صَدَّقوا الله ورسوله وعملوا بشرعه، إذا قابلتم الذين كفروا في القتال متقاربين منكم فلا تُوَلُّوهم ظهوركم، فتنهزموا عنهم، ولكن اثبتوا لهم، فإن الله معكم وناصركم عليهم."},{"id":"1176","jozz":"9","page":"178","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"13","line_end":"15","aya_no":"16","aya_text":"وَمَن يُوَلِّهِمۡ يَوۡمَئِذٖ دُبُرَهُۥٓ إِلَّا مُتَحَرِّفٗا لِّقِتَالٍ أَوۡ مُتَحَيِّزًا إِلَىٰ فِئَةٖ فَقَدۡ بَآءَ بِغَضَبٖ مِّنَ ٱللَّهِ وَمَأۡوَىٰهُ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِيرُ","aya_text_emlaey":"ومن يولهم يومئذ دبره إلا متحرفا لقتال أو متحيزا إلى فئة فقد باء بغضب من الله ومأواه جهنم وبئس المصير","aya_tafseer":"[16] ومَن يُوَلِّهم منكم ظهره وقت الزحف، إلا منعطفاً لمكيدة الكفار، أو منحازاً إلى جماعة المسلمين الحاضري الحرب حيث كانوا، فقد استحق الغضب من الله، ومَقامه جهنم، وبئس المصير والمنقلب."},{"id":"1177","jozz":"9","page":"179","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"1","line_end":"3","aya_no":"17","aya_text":"فَلَمۡ تَقۡتُلُوهُمۡ وَلَٰكِنَّ ٱللَّهَ قَتَلَهُمۡۚ وَمَا رَمَيۡتَ إِذۡ رَمَيۡتَ وَلَٰكِنَّ ٱللَّهَ رَمَىٰ وَلِيُبۡلِيَ ٱلۡمُؤۡمِنِينَ مِنۡهُ بَلَآءً حَسَنًاۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ","aya_text_emlaey":"فلم تقتلوهم ولكن الله قتلهم وما رميت إذ رميت ولكن الله رمى وليبلي المؤمنين منه بلاء حسنا إن الله سميع عليم","aya_tafseer":"[17] فلم تقتلوا -أيها المؤمنون- المشركين يوم «بدر»، ولكن الله قتلهم، حيث أعانكم على ذلك، وما رميت حين رميت -أيها النبي- ولكن الله رمى، حيث أوصل الرمية التي رميتها إلى وجوه المشركين؛ وليختبر المؤمنين بالله ورسوله ويوصلهم بالجهاد إلى أعلى الدرجات، ويعرِّفهم نعمته عليهم، فيشكروا له سبحانه على ذلك. إن الله سميع لدعائكم وأقوالكم ما أسررتم به وما أعلنتم، عليم بما فيه صلاح عباده."},{"id":"1178","jozz":"9","page":"179","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"3","line_end":"4","aya_no":"18","aya_text":"ذَٰلِكُمۡ وَأَنَّ ٱللَّهَ مُوهِنُ كَيۡدِ ٱلۡكَٰفِرِينَ","aya_text_emlaey":"ذلكم وأن الله موهن كيد الكافرين","aya_tafseer":"[18] هذا الفعل من قتل المشركين ورميهم حين انهزموا، والبلاء الحسن بنصر المؤمنين على أعدائهم، هو من الله للمؤمنين، وأن الله -فيما يُسْتقبل- مُضعِف ومُبطِل مكر الكافرين حتى يَذِلُّوا وينقادوا للحق أو يهلكوا."},{"id":"1179","jozz":"9","page":"179","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"4","line_end":"6","aya_no":"19","aya_text":"إِن تَسۡتَفۡتِحُواْ فَقَدۡ جَآءَكُمُ ٱلۡفَتۡحُۖ وَإِن تَنتَهُواْ فَهُوَ خَيۡرٞ لَّكُمۡۖ وَإِن تَعُودُواْ نَعُدۡ وَلَن تُغۡنِيَ عَنكُمۡ فِئَتُكُمۡ شَيۡـٔٗا وَلَوۡ كَثُرَتۡ وَأَنَّ ٱللَّهَ مَعَ ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"إن تستفتحوا فقد جاءكم الفتح وإن تنتهوا فهو خير لكم وإن تعودوا نعد ولن تغني عنكم فئتكم شيئا ولو كثرت وأن الله مع المؤمنين","aya_tafseer":"[19] إن تطلبوا -أيها الكفار- من الله أن يوقع بأسه وعذابه على المعتدين الظالمين فقد أجاب الله طلبكم، حين أوقع بكم مِن عقابه ما كان نكالاً لكم وعبرة للمتقين، وإن تنتهوا -أيها الكفار- عن الكفر بالله ورسوله وقتال نبيه محمد -صلى الله عليه وسلم-، فهو خير لكم في دنياكم وأخراكم، وإن تعودوا إلى الحرب وقتال محمد -صلى الله عليه وسلم- وقتال أتباعه المؤمنين نَعُدْ بهزيمتكم كما هُزمتم يوم «بدر»، ولن تغني عنكم جماعتكم شيئاً، كما لم تغن عنكم يوم «بدر» مع كثرة عددكم وعتادكم وقلة عدد المؤمنين وعدتهم، وأن الله مع المؤمنين بتأييده ونصره."},{"id":"1180","jozz":"9","page":"179","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"7","line_end":"8","aya_no":"20","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَوَلَّوۡاْ عَنۡهُ وَأَنتُمۡ تَسۡمَعُونَ","aya_text_emlaey":"ياأيها الذين آمنوا أطيعوا الله ورسوله ولا تولوا عنه وأنتم تسمعون","aya_tafseer":"[20] يا أيها الذين صدَّقوا الله ورسوله أطيعوا الله ورسوله فيما أمركم به ونهاكم عنه، ولا تتركوا طاعة الله وطاعة رسوله، وأنتم تسمعون ما يتلى عليكم في القرآن من الحجج والبراهين."},{"id":"1181","jozz":"9","page":"179","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"8","line_end":"9","aya_no":"21","aya_text":"وَلَا تَكُونُواْ كَٱلَّذِينَ قَالُواْ سَمِعۡنَا وَهُمۡ لَا يَسۡمَعُونَ","aya_text_emlaey":"ولا تكونوا كالذين قالوا سمعنا وهم لا يسمعون","aya_tafseer":"[21] ولا تكونوا أيها المؤمنون في مخالفة الله ورسوله محمد -صلى الله عليه وسلم- كالمشركين والمنافقين الذين إذا سمعوا كتاب الله يتلى عليهم قالوا: سمعنا بآذاننا، وهم في الحقيقة لا يتدبرون ما سمعوا، ولا يفكرون فيه."},{"id":"1182","jozz":"9","page":"179","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"9","line_end":"10","aya_no":"22","aya_text":"۞ إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلۡبُكۡمُ ٱلَّذِينَ لَا يَعۡقِلُونَ","aya_text_emlaey":"إن شر الدواب عند الله الصم البكم الذين لا يعقلون","aya_tafseer":"[22] إنَّ شر ما دبَّ على الأرض -مِن خَلْق الله- عند الله الصمُّ الذين انسدَّت آذانهم عن سماع الحق فلا يسمعون، البكم الذين خَرِست ألسنتهم عن النطق به فلا ينطقون، هؤلاء هم الذين لا يعقلون عن الله أمره ونهيه."},{"id":"1183","jozz":"9","page":"179","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"10","line_end":"11","aya_no":"23","aya_text":"وَلَوۡ عَلِمَ ٱللَّهُ فِيهِمۡ خَيۡرٗا لَّأَسۡمَعَهُمۡۖ وَلَوۡ أَسۡمَعَهُمۡ لَتَوَلَّواْ وَّهُم مُّعۡرِضُونَ","aya_text_emlaey":"ولو علم الله فيهم خيرا لأسمعهم ولو أسمعهم لتولوا وهم معرضون","aya_tafseer":"[23] ولو علم الله في هؤلاء خيراً لأسمعهم مواعظ القرآن وعبره حتى يعقلوا عن الله عز وجل حججه وبراهينه، ولكنه علم أنه لا خير فيهم وأنهم لا يؤمنون، ولو أسمعهم -على الفرض والتقدير- لتولَّوا عن الإيمان قصداً وعناداً بعد فهمهم له، وهم معرضون عنه، لا التفات لهم إلى الحق بوجه من الوجوه."},{"id":"1184","jozz":"9","page":"179","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"11","line_end":"14","aya_no":"24","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱسۡتَجِيبُواْ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمۡ لِمَا يُحۡيِيكُمۡۖ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَحُولُ بَيۡنَ ٱلۡمَرۡءِ وَقَلۡبِهِۦ وَأَنَّهُۥٓ إِلَيۡهِ تُحۡشَرُونَ","aya_text_emlaey":"ياأيها الذين آمنوا استجيبوا لله وللرسول إذا دعاكم لما يحييكم واعلموا أن الله يحول بين المرء وقلبه وأنه إليه تحشرون","aya_tafseer":"[24] يا أيها الذين صدَّقوا بالله ربّاً وبمحمد نبيّاً ورسولاً، استجيبوا لله وللرسول بالطاعة إذا دعاكم لما يحييكم من الحق، ففي الاستجابة إصلاح حياتكم في الدنيا والآخرة، واعلموا -أيها المؤمنون- أن الله تعالى هو المتصرف في جميع الأشياء، والقادر على أن يحول بين الإنسان وما يشتهيه قلبه، فهو سبحانه الذي ينبغي أن يستجاب له إذا دعاكم؛ إذ بيده ملكوت كل شيء، واعلموا أنكم تُجمَعون ليوم لا ريب فيه، فيجازي كُلّاً بما يستحق."},{"id":"1185","jozz":"9","page":"179","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"14","line_end":"15","aya_no":"25","aya_text":"وَٱتَّقُواْ فِتۡنَةٗ لَّا تُصِيبَنَّ ٱلَّذِينَ ظَلَمُواْ مِنكُمۡ خَآصَّةٗۖ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ","aya_text_emlaey":"واتقوا فتنة لا تصيبن الذين ظلموا منكم خاصة واعلموا أن الله شديد العقاب","aya_tafseer":"[25] واحذروا -أيها المؤمنون- اختباراً ومحنة يُعَمُّ بها المسيء وغيره، لا يُخَص بها أهل المعاصي ولا مَن باشر الذنب، بل تصيب الصالحين معهم إذا قَدَروا على إنكار الظلم ولم ينكروه، واعلموا أن الله شديد العقاب لمن خالف أمره ونهيه."},{"id":"1186","jozz":"9","page":"180","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"1","line_end":"3","aya_no":"26","aya_text":"وَٱذۡكُرُوٓاْ إِذۡ أَنتُمۡ قَلِيلٞ مُّسۡتَضۡعَفُونَ فِي ٱلۡأَرۡضِ تَخَافُونَ أَن يَتَخَطَّفَكُمُ ٱلنَّاسُ فَـَٔاوَىٰكُمۡ وَأَيَّدَكُم بِنَصۡرِهِۦ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِ لَعَلَّكُمۡ تَشۡكُرُونَ","aya_text_emlaey":"واذكروا إذ أنتم قليل مستضعفون في الأرض تخافون أن يتخطفكم الناس فآواكم وأيدكم بنصره ورزقكم من الطيبات لعلكم تشكرون","aya_tafseer":"[26] واذكروا أيها المؤمنون نِعَم الله عليكم إذ أنتم ﺑ«مكة» قليلو العدد مقهورون، تخافون أن يأخذكم كفارُها بسرعة، فجعل لكم مأوى تأوون إليه وهو «المدينة»، وقوَّاكم بنصره عليهم يوم «بدر»، وأطعمكم من الطيبات -التي من جملتها الغنائم-؛ لكي تشكروا له على ما رزقكم وأنعم به عليكم."},{"id":"1187","jozz":"9","page":"180","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"3","line_end":"4","aya_no":"27","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَخُونُواْ ٱللَّهَ وَٱلرَّسُولَ وَتَخُونُوٓاْ أَمَٰنَٰتِكُمۡ وَأَنتُمۡ تَعۡلَمُونَ","aya_text_emlaey":"ياأيها الذين آمنوا لا تخونوا الله والرسول وتخونوا أماناتكم وأنتم تعلمون","aya_tafseer":"[27] يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه لا تخونوا الله ورسوله بترك ما أوجبه الله عليكم وفِعْل ما نهاكم عنه، ولا تفرِّطوا فيما ائتمنكم الله عليه، وأنتم تعلمون أنه أمانة يجب الوفاء بها."},{"id":"1188","jozz":"9","page":"180","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"5","line_end":"6","aya_no":"28","aya_text":"وَٱعۡلَمُوٓاْ أَنَّمَآ أَمۡوَٰلُكُمۡ وَأَوۡلَٰدُكُمۡ فِتۡنَةٞ وَأَنَّ ٱللَّهَ عِندَهُۥٓ أَجۡرٌ عَظِيمٞ","aya_text_emlaey":"واعلموا أنما أموالكم وأولادكم فتنة وأن الله عنده أجر عظيم","aya_tafseer":"[28] واعلموا -أيها المؤمنون- أن أموالكم التي استخلفكم الله فيها، وأولادكم الذين وهبهم الله لكم اختبار من الله وابتلاء لعباده؛ ليعلم أيشكرونه عليها ويطيعونه فيها، أم ينشغلون بها عنه؟ واعلموا أن الله عنده خير وثواب عظيم لمن اتقاه وأطاعه."},{"id":"1189","jozz":"9","page":"180","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"6","line_end":"8","aya_no":"29","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تَتَّقُواْ ٱللَّهَ يَجۡعَل لَّكُمۡ فُرۡقَانٗا وَيُكَفِّرۡ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَيَغۡفِرۡ لَكُمۡۗ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ","aya_text_emlaey":"ياأيها الذين آمنوا إن تتقوا الله يجعل لكم فرقانا ويكفر عنكم سيئاتكم ويغفر لكم والله ذو الفضل العظيم","aya_tafseer":"[29] يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه إن تتقوا الله بفعل أوامره واجتناب نواهيه يجعل لكم فَصْلاً بين الحق والباطل، ويَمحُ عنكم ما سلف من ذنوبكم ويستُرْها عليكم، فلا يؤاخذكم بها. والله ذو الإحسان والعطاء الكثير الواسع."},{"id":"1190","jozz":"9","page":"180","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"8","line_end":"10","aya_no":"30","aya_text":"وَإِذۡ يَمۡكُرُ بِكَ ٱلَّذِينَ كَفَرُواْ لِيُثۡبِتُوكَ أَوۡ يَقۡتُلُوكَ أَوۡ يُخۡرِجُوكَۚ وَيَمۡكُرُونَ وَيَمۡكُرُ ٱللَّهُۖ وَٱللَّهُ خَيۡرُ ٱلۡمَٰكِرِينَ","aya_text_emlaey":"وإذ يمكر بك الذين كفروا ليثبتوك أو يقتلوك أو يخرجوك ويمكرون ويمكر الله والله خير الماكرين","aya_tafseer":"[30] واذكر -أيها الرسول- حين يكيد لك مشركو قومك ﺑ«مكَّة»؛ ليحبسوك أو يقتلوك أو ينفوك من بلدك. ويكيدون لك، وردَّ الله مكرهم عليهم جزاء لهم، ويمكر الله، والله خير الماكرين، فهو يعاقبهم على مكرهم من حيث لا يشعرون."},{"id":"1191","jozz":"9","page":"180","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"10","line_end":"12","aya_no":"31","aya_text":"وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا قَالُواْ قَدۡ سَمِعۡنَا لَوۡ نَشَآءُ لَقُلۡنَا مِثۡلَ هَٰذَآ إِنۡ هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ","aya_text_emlaey":"وإذا تتلى عليهم آياتنا قالوا قد سمعنا لو نشاء لقلنا مثل هذا إن هذا إلا أساطير الأولين","aya_tafseer":"[31] وإذا تتلى على هؤلاء الذين كفروا بالله آياتُ القرآن العزيز قالوا جهلاً منهم وعناداً للحق: قد سمعنا هذا من قبل، لو نشاء لقلنا مثل هذا القرآن، ما هذا القرآن الذي تتلوه علينا -أيها الرسول- إلا أكاذيب الأولين."},{"id":"1192","jozz":"9","page":"180","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"12","line_end":"14","aya_no":"32","aya_text":"وَإِذۡ قَالُواْ ٱللَّهُمَّ إِن كَانَ هَٰذَا هُوَ ٱلۡحَقَّ مِنۡ عِندِكَ فَأَمۡطِرۡ عَلَيۡنَا حِجَارَةٗ مِّنَ ٱلسَّمَآءِ أَوِ ٱئۡتِنَا بِعَذَابٍ أَلِيمٖ","aya_text_emlaey":"وإذ قالوا اللهم إن كان هذا هو الحق من عندك فأمطر علينا حجارة من السماء أو ائتنا بعذاب أليم","aya_tafseer":"[32] واذكر -أيها الرسول- قول المشركين من قومك داعين الله: إن كان ما جاء به محمد هو الحق مِن عندك فأمطر علينا حجارة من السماء، أو ائتنا بعذاب شديد موجع."},{"id":"1193","jozz":"9","page":"180","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"14","line_end":"15","aya_no":"33","aya_text":"وَمَا كَانَ ٱللَّهُ لِيُعَذِّبَهُمۡ وَأَنتَ فِيهِمۡۚ وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمۡ وَهُمۡ يَسۡتَغۡفِرُونَ","aya_text_emlaey":"وما كان الله ليعذبهم وأنت فيهم وما كان الله معذبهم وهم يستغفرون","aya_tafseer":"[33] وما كان الله - سبحانه وتعالى - ليعذِّب هؤلاء المشركين، وأنت -أيها الرسول- بين ظهرانَيْهم، وما كان الله معذِّبهم، وهم يستغفرون من ذنوبهم."},{"id":"1194","jozz":"9","page":"181","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"1","line_end":"3","aya_no":"34","aya_text":"وَمَا لَهُمۡ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ وَهُمۡ يَصُدُّونَ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَمَا كَانُوٓاْ أَوۡلِيَآءَهُۥٓۚ إِنۡ أَوۡلِيَآؤُهُۥٓ إِلَّا ٱلۡمُتَّقُونَ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ","aya_text_emlaey":"وما لهم ألا يعذبهم الله وهم يصدون عن المسجد الحرام وما كانوا أولياءه إن أولياؤه إلا المتقون ولكن أكثرهم لا يعلمون","aya_tafseer":"[34] وكيف لا يستحقُّون عذاب الله، وهم يصدون أولياءه المؤمنين عن الطواف بالكعبة والصلاة في المسجد الحرام؟ وما كانوا أولياء الله، إنْ أولياء الله إلا الذين يتقونه بأداء فرائضه واجتناب معاصيه، ولكن أكثر الكفار لا يعلمون؛ فلذلك ادَّعوا لأنفسهم أمراً، غيرُهم أولى به."},{"id":"1195","jozz":"9","page":"181","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"3","line_end":"5","aya_no":"35","aya_text":"وَمَا كَانَ صَلَاتُهُمۡ عِندَ ٱلۡبَيۡتِ إِلَّا مُكَآءٗ وَتَصۡدِيَةٗۚ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ","aya_text_emlaey":"وما كان صلاتهم عند البيت إلا مكاء وتصدية فذوقوا العذاب بما كنتم تكفرون","aya_tafseer":"[35] وما كان صلاتهم عند المسجد الحرام إلا صفيراً وتصفيقاً. فذوقوا عذاب القتل والأسر يوم «بدر»؛ بسبب جحودكم وأفعالكم التي لا يُقْدم عليها إلا الكفرة، الجاحدون توحيدَ ربهم ورسالةَ نبيهم."},{"id":"1196","jozz":"9","page":"181","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"5","line_end":"8","aya_no":"36","aya_text":"إِنَّ ٱلَّذِينَ كَفَرُواْ يُنفِقُونَ أَمۡوَٰلَهُمۡ لِيَصُدُّواْ عَن سَبِيلِ ٱللَّهِۚ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيۡهِمۡ حَسۡرَةٗ ثُمَّ يُغۡلَبُونَۗ وَٱلَّذِينَ كَفَرُوٓاْ إِلَىٰ جَهَنَّمَ يُحۡشَرُونَ","aya_text_emlaey":"إن الذين كفروا ينفقون أموالهم ليصدوا عن سبيل الله فسينفقونها ثم تكون عليهم حسرة ثم يغلبون والذين كفروا إلى جهنم يحشرون","aya_tafseer":"[36] إن الذين جحدوا وحدانية الله وعصوا رسوله ينفقون أموالهم فيعطونها أمثالهم من المشركين وأهل الضلال؛ ليصدوا عن سبيل الله ويمنعوا المؤمنين عن الإيمان بالله ورسوله، فسينفقون أموالهم في ذلك، ثم تكون عاقبة نفقتهم تلك ندامة وحسرة عليهم؛ لأن أموالهم تذهب، ولا يظفرون بما يأمُلون مِن إطفاء نور الله والصد عن سبيله، ثم يهزمهم المؤمنون آخر الأمر. والذين كفروا إلى جهنم يحشرون فيعذبون فيها."},{"id":"1197","jozz":"9","page":"181","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"8","line_end":"10","aya_no":"37","aya_text":"لِيَمِيزَ ٱللَّهُ ٱلۡخَبِيثَ مِنَ ٱلطَّيِّبِ وَيَجۡعَلَ ٱلۡخَبِيثَ بَعۡضَهُۥ عَلَىٰ بَعۡضٖ فَيَرۡكُمَهُۥ جَمِيعٗا فَيَجۡعَلَهُۥ فِي جَهَنَّمَۚ أُوْلَٰٓئِكَ هُمُ ٱلۡخَٰسِرُونَ","aya_text_emlaey":"ليميز الله الخبيث من الطيب ويجعل الخبيث بعضه على بعض فيركمه جميعا فيجعله في جهنم أولئك هم الخاسرون","aya_tafseer":"[37] يحشر الله ويخزي هؤلاء الذين كفروا بربهم، وأنفقوا أموالهم لمنع الناس عن الإيمان بالله والصد عن سبيله؛ ليميز الله تعالى الخبيث من الطيب، ويجعل الله المال الحرام الذي أُنفق للصدِّ عن دين الله بعضه فوق بعض متراكماً متراكباً، فيجعله في نار جهنم، هؤلاء الكفار هم الخاسرون في الدنيا والآخرة."},{"id":"1198","jozz":"9","page":"181","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"10","line_end":"12","aya_no":"38","aya_text":"قُل لِّلَّذِينَ كَفَرُوٓاْ إِن يَنتَهُواْ يُغۡفَرۡ لَهُم مَّا قَدۡ سَلَفَ وَإِن يَعُودُواْ فَقَدۡ مَضَتۡ سُنَّتُ ٱلۡأَوَّلِينَ","aya_text_emlaey":"قل للذين كفروا إن ينتهوا يغفر لهم ما قد سلف وإن يعودوا فقد مضت سنة الأولين","aya_tafseer":"[38] قل -أيها الرسول- للذين جحدوا وحدانية الله مِن مشركي قومك: إن ينزجروا عن الكفر وعداوة النبي -صلى الله عليه وسلم-، ويرجعوا إلى الإيمان بالله وحده وعدم قتال الرسول والمؤمنين، يغفر الله لهم ما سبق من الذنوب، فالإسلام يَجُبُّ ما قبله. وإن يَعُدْ هؤلاء المشركون لقتالك -أيها الرسول- بعد الوقعة التي أوقعتها بهم يوم «بدر» فقد سبقت طريقة الأولين، وهي أنهم إذا كذبوا واستمروا على عنادهم عاجلناهم بالعذاب والعقوبة."},{"id":"1199","jozz":"9","page":"181","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"12","line_end":"14","aya_no":"39","aya_text":"وَقَٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةٞ وَيَكُونَ ٱلدِّينُ كُلُّهُۥ لِلَّهِۚ فَإِنِ ٱنتَهَوۡاْ فَإِنَّ ٱللَّهَ بِمَا يَعۡمَلُونَ بَصِيرٞ","aya_text_emlaey":"وقاتلوهم حتى لا تكون فتنة ويكون الدين كله لله فإن انتهوا فإن الله بما يعملون بصير","aya_tafseer":"[39] وقاتلوا -أيها المؤمنون- المشركين حتى لا يكون شِرْكٌ وصدٌّ عن سبيل الله، ولا يُعْبَدَ إلا الله وحده لا شريك له، فيرتفع البلاء عن عباد الله في الأرض، وحتى يكون الدين والطاعة والعبادة كلها لله خالصة دون غيره، فإن انزجروا عن فتنة المؤمنين وعن الشرك بالله وصاروا إلى الدين الحق معكم، فإن الله لا يخفى عليه ما يعملون مِن ترك الكفر والدخول في الإسلام."},{"id":"1200","jozz":"9","page":"181","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"14","line_end":"15","aya_no":"40","aya_text":"وَإِن تَوَلَّوۡاْ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَوۡلَىٰكُمۡۚ نِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِيرُ","aya_text_emlaey":"وإن تولوا فاعلموا أن الله مولاكم نعم المولى ونعم النصير","aya_tafseer":"[40] وإن أعرض هؤلاء المشركون عمَّا دعوتموهم إليه -أيها المؤمنون- من الإيمان بالله ورسوله وترك قتالكم، وأبَوْا إلا الإصرار على الكفر وقتالكم، فأيقِنوا أن الله معينكم وناصركم عليهم. نِعْمَ المعين والناصر لكم ولأوليائه على أعدائكم."},{"id":"1201","jozz":"10","page":"182","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"1","line_end":"4","aya_no":"41","aya_text":"۞ وَٱعۡلَمُوٓاْ أَنَّمَا غَنِمۡتُم مِّن شَيۡءٖ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِ إِن كُنتُمۡ ءَامَنتُم بِٱللَّهِ وَمَآ أَنزَلۡنَا عَلَىٰ عَبۡدِنَا يَوۡمَ ٱلۡفُرۡقَانِ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ","aya_text_emlaey":"واعلموا أنما غنمتم من شيء فأن لله خمسه وللرسول ولذي القربى واليتامى والمساكين وابن السبيل إن كنتم آمنتم بالله وما أنـزلنا على عبدنا يوم الفرقان يوم التقى الجمعان والله على كل شيء قدير","aya_tafseer":"[41] واعلموا -أيها المؤمنون- أن ما ظَفِرتم به مِن عدوكم بالجهاد في سبيل الله فأربعة أخماسه للمقاتلين الذين حضروا المعركة، والخمس الباقي يجزَّأُ خمسة أقسام: الأول لله وللرسول، فيجعل في مصالح المسلمين العامة، والثاني لذوي قرابة رسول الله -صلى الله عليه وسلم-، وهم بنو هاشم وبنو المطلب، جُعِل لهم الخمس مكان الصدقة فإنها لا تحلُّ لهم، والثالث للأولاد الذين مات آباؤهم وهم دون سن البلوغ، والرابع للمساكين الذين لا يملكون ما يكفيهم ويسدُّ حاجتهم، والخامس للمسافر الذي انقطعت به النفقة، إن كنتم مقرِّين بتوحيد الله مطيعين له، مؤمنين بما أنزل على عبده محمد -صلى الله عليه وسلم- من الآيات والمدد والنصر يوم فَرَق بين الحق والباطل ﺑ«بدر»، يوم التقى جَمْعُ المؤمنين وجَمْعُ المشركين. والله على كل شيء قدير لا يعجزه شيء."},{"id":"1202","jozz":"10","page":"182","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"4","line_end":"9","aya_no":"42","aya_text":"إِذۡ أَنتُم بِٱلۡعُدۡوَةِ ٱلدُّنۡيَا وَهُم بِٱلۡعُدۡوَةِ ٱلۡقُصۡوَىٰ وَٱلرَّكۡبُ أَسۡفَلَ مِنكُمۡۚ وَلَوۡ تَوَاعَدتُّمۡ لَٱخۡتَلَفۡتُمۡ فِي ٱلۡمِيعَٰدِ وَلَٰكِن لِّيَقۡضِيَ ٱللَّهُ أَمۡرٗا كَانَ مَفۡعُولٗا لِّيَهۡلِكَ مَنۡ هَلَكَ عَنۢ بَيِّنَةٖ وَيَحۡيَىٰ مَنۡ حَيَّ عَنۢ بَيِّنَةٖۗ وَإِنَّ ٱللَّهَ لَسَمِيعٌ عَلِيمٌ","aya_text_emlaey":"إذ أنتم بالعدوة الدنيا وهم بالعدوة القصوى والركب أسفل منكم ولو تواعدتم لاختلفتم في الميعاد ولكن ليقضي الله أمرا كان مفعولا ليهلك من هلك عن بينة ويحيا من حي عن بينة وإن الله لسميع عليم","aya_tafseer":"[42] واذكروا حينما كنتم على جانب الوادي الأقرب إلى «المدينة»، وعدوكم نازل بجانب الوادي الأقصى، وعِير التجارة في مكان أسفل منكم إلى ساحل «البحر الأحمر»، ولو حاولتم أن تضعوا موعداً لهذا اللقاء لاختلفتم، ولكنَّ الله جمعكم على غير ميعاد؛ ليقضي أمراً كان مفعولاً بنصر أوليائه وخِذْلان أعدائه بالقتل والأسر؛ وذلك ليهلك مَن هلك منهم عن حجة لله ثبتت له فعاينها وقطعت عذره، وليحيا مَن حيَّ عن حجة لله قد ثبتت وظهرت له. وإن الله لَسميع لأقوال الفريقين، لا يخفى عليه شيء، عليم بنيَّاتهم وأعمالهم."},{"id":"1203","jozz":"10","page":"182","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"9","line_end":"11","aya_no":"43","aya_text":"إِذۡ يُرِيكَهُمُ ٱللَّهُ فِي مَنَامِكَ قَلِيلٗاۖ وَلَوۡ أَرَىٰكَهُمۡ كَثِيرٗا لَّفَشِلۡتُمۡ وَلَتَنَٰزَعۡتُمۡ فِي ٱلۡأَمۡرِ وَلَٰكِنَّ ٱللَّهَ سَلَّمَۚ إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ","aya_text_emlaey":"إذ يريكهم الله في منامك قليلا ولو أراكهم كثيرا لفشلتم ولتنازعتم في الأمر ولكن الله سلم إنه عليم بذات الصدور","aya_tafseer":"[43] واذكر -أيها النبي- حينما أراك الله قلة عدد عدوك في منامك، فأخبرت المؤمنين بذلك، فقوِيت قلوبهم، واجترؤوا على حربهم، ولو أراك ربك كثرة عددهم لتردد أصحابك في ملاقاتهم، وجَبُنتم واختلفتم في أمر القتال، ولكن الله سلَّم من الفشل، ونجَّى من عاقبة ذلك. إنه عليم بخفايا القلوب وطبائع النفوس."},{"id":"1204","jozz":"10","page":"182","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"11","line_end":"14","aya_no":"44","aya_text":"وَإِذۡ يُرِيكُمُوهُمۡ إِذِ ٱلۡتَقَيۡتُمۡ فِيٓ أَعۡيُنِكُمۡ قَلِيلٗا وَيُقَلِّلُكُمۡ فِيٓ أَعۡيُنِهِمۡ لِيَقۡضِيَ ٱللَّهُ أَمۡرٗا كَانَ مَفۡعُولٗاۗ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ","aya_text_emlaey":"وإذ يريكموهم إذ التقيتم في أعينكم قليلا ويقللكم في أعينهم ليقضي الله أمرا كان مفعولا وإلى الله ترجع الأمور","aya_tafseer":"[44] واذكر أيضاً حينما برز الأعداء إلى أرض المعركة فرأيتموهم قليلاً فاجترأتم عليهم، وقلَّلكم في أعينهم؛ ليتركوا الاستعداد لحربكم؛ ليقضي الله أمراً كان مفعولاً، فيتحقق وَعْدُ الله لكم بالنصر والغلبة، فكانت كلمة الله هي العليا وكلمة الذين كفروا السفلى. وإلى الله مصير الأمور كلها، فيجازي كُلّاً بما يستحق."},{"id":"1205","jozz":"10","page":"182","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"14","line_end":"15","aya_no":"45","aya_text":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا لَقِيتُمۡ فِئَةٗ فَٱثۡبُتُواْ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ","aya_text_emlaey":"ياأيها الذين آمنوا إذا لقيتم فئة فاثبتوا واذكروا الله كثيرا لعلكم تفلحون","aya_tafseer":"[45] يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، إذا لقيتم جماعة من أهل الكفر قد استعدوا لقتالكم، فاثبتوا ولا تنهزموا عنهم، واذكروا الله كثيراً داعين مبتهلين لإنزال النصر عليكم والظَّفَر بعدوكم؛ لكي تفوزوا."},{"id":"1206","jozz":"10","page":"183","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"1","line_end":"2","aya_no":"46","aya_text":"وَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَٰزَعُواْ فَتَفۡشَلُواْ وَتَذۡهَبَ رِيحُكُمۡۖ وَٱصۡبِرُوٓاْۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ","aya_text_emlaey":"وأطيعوا الله ورسوله ولا تنازعوا فتفشلوا وتذهب ريحكم واصبروا إن الله مع الصابرين","aya_tafseer":"[46] والتزموا طاعة الله وطاعة رسوله في كل أحوالكم، ولا تختلفوا فتتفرق كلمتكم وتختلف قلوبكم، فتضعُفوا وتذهب قوتكم ونصركم، واصبروا عند لقاء العدو. إن الله مع الصابرين بالعون والنصر والتأييد، ولن يخذلهم."},{"id":"1207","jozz":"10","page":"183","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"2","line_end":"4","aya_no":"47","aya_text":"وَلَا تَكُونُواْ كَٱلَّذِينَ خَرَجُواْ مِن دِيَٰرِهِم بَطَرٗا وَرِئَآءَ ٱلنَّاسِ وَيَصُدُّونَ عَن سَبِيلِ ٱللَّهِۚ وَٱللَّهُ بِمَا يَعۡمَلُونَ مُحِيطٞ","aya_text_emlaey":"ولا تكونوا كالذين خرجوا من ديارهم بطرا ورئاء الناس ويصدون عن سبيل الله والله بما يعملون محيط","aya_tafseer":"[47] ولا تكونوا مثل المشركين الذين خرجوا من بلدهم كِبْراً ورياءً؛ ليمنعوا الناس عن الدخول في دين الله. والله بما يعملون محيط لا يغيب عنه شيء."},{"id":"1208","jozz":"10","page":"183","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"4","line_end":"8","aya_no":"48","aya_text":"وَإِذۡ زَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ وَقَالَ لَا غَالِبَ لَكُمُ ٱلۡيَوۡمَ مِنَ ٱلنَّاسِ وَإِنِّي جَارٞ لَّكُمۡۖ فَلَمَّا تَرَآءَتِ ٱلۡفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَيۡهِ وَقَالَ إِنِّي بَرِيٓءٞ مِّنكُمۡ إِنِّيٓ أَرَىٰ مَا لَا تَرَوۡنَ إِنِّيٓ أَخَافُ ٱللَّهَۚ وَٱللَّهُ شَدِيدُ ٱلۡعِقَابِ","aya_text_emlaey":"وإذ زين لهم الشيطان أعمالهم وقال لا غالب لكم اليوم من الناس وإني جار لكم فلما تراءت الفئتان نكص على عقبيه وقال إني بريء منكم إني أرى ما لا ترون إني أخاف الله والله شديد العقاب","aya_tafseer":"[48] واذكروا حين حسَّن الشيطان للمشركين ما جاؤوا له وما همُّوا به، وقال لهم: لن يغلبكم أحد اليوم، وإني ناصركم، فلما تقابل الفريقان: المشركون ومعهم الشيطان، والمسلمون ومعهم الملائكة، رجع الشيطان مُدْبراً، وقال للمشركين: إني بريء منكم، إني أرى ما لا ترون من الملائكة الذين جاؤوا مدداً للمسلمين، إني أخاف الله، فخذلهم وتبرأ منهم. والله شديد العقاب لمن عصاه ولم يتب توبة نصوحاً."},{"id":"1209","jozz":"10","page":"183","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"8","line_end":"10","aya_no":"49","aya_text":"إِذۡ يَقُولُ ٱلۡمُنَٰفِقُونَ وَٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٌ غَرَّ هَٰٓؤُلَآءِ دِينُهُمۡۗ وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَإِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ","aya_text_emlaey":"إذ يقول المنافقون والذين في قلوبهم مرض غر هؤلاء دينهم ومن يتوكل على الله فإن الله عزيز حكيم","aya_tafseer":"[49] واذكروا حين يقول أهل الشك والنفاق ومرضى القلوب، وهم يرون قلة المسلمين وكثرة عدوهم: غرَّ هؤلاء المسلمين دينُهم، فأوردهم هذه الموارد، ولم يدرك هؤلاء المنافقون أنه من يتوكل على الله ويثق بوعده فإن الله لن يخذله، فإن الله عزيز لا يعجزه شيء، حكيم في تدبيره وصنعه."},{"id":"1210","jozz":"10","page":"183","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"10","line_end":"12","aya_no":"50","aya_text":"وَلَوۡ تَرَىٰٓ إِذۡ يَتَوَفَّى ٱلَّذِينَ كَفَرُواْ ٱلۡمَلَٰٓئِكَةُ يَضۡرِبُونَ وُجُوهَهُمۡ وَأَدۡبَٰرَهُمۡ وَذُوقُواْ عَذَابَ ٱلۡحَرِيقِ","aya_text_emlaey":"ولو ترى إذ يتوفى الذين كفروا الملائكة يضربون وجوههم وأدبارهم وذوقوا عذاب الحريق","aya_tafseer":"[50] ولو تعاين -أيها الرسول- حال قبض الملائكة أرواح الكفار وانتزاعها، وهم يضربون وجوههم في حال إقبالهم، ويضربون ظهورهم في حال فرارهم، ويقولون لهم: ذوقوا العذاب المحرق، لرأيت أمراً عظيماً. وهذا السياق وإن كان سببه وقعة «بدر»، ولكنه عام في حق كلِّ كافر."},{"id":"1211","jozz":"10","page":"183","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"12","line_end":"13","aya_no":"51","aya_text":"ذَٰلِكَ بِمَا قَدَّمَتۡ أَيۡدِيكُمۡ وَأَنَّ ٱللَّهَ لَيۡسَ بِظَلَّٰمٖ لِّلۡعَبِيدِ","aya_text_emlaey":"ذلك بما قدمت أيديكم وأن الله ليس بظلام للعبيد","aya_tafseer":"[51] ذلك الجزاء الذي أصابكم أيها المشركون فبسبب أعمالكم السيئة في حياتكم الدنيا، ولا يظلم الله أحداً مِن خَلْقه مثقال ذرة، بل هو الحَكَمُ العدل الذي لا يجور."},{"id":"1212","jozz":"10","page":"183","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"14","line_end":"15","aya_no":"52","aya_text":"كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡۚ إِنَّ ٱللَّهَ قَوِيّٞ شَدِيدُ ٱلۡعِقَابِ","aya_text_emlaey":"كدأب آل فرعون والذين من قبلهم كفروا بآيات الله فأخذهم الله بذنوبهم إن الله قوي شديد العقاب","aya_tafseer":"[52] إنَّ ما نزل بالمشركين يومئذ سُنَّة الله في عقاب الطغاة من الأمم السابقة من أمثال فرعون والسابقين له، عندما كذَّبوا رسل الله وجحدوا آياته، فإن الله أنزل بهم عقابه بسبب ذنوبهم. إن الله قوي لا يُقْهر، شديد العقاب لمن عصاه ولم يتب من ذنبه."},{"id":"1213","jozz":"10","page":"184","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"1","line_end":"2","aya_no":"53","aya_text":"ذَٰلِكَ بِأَنَّ ٱللَّهَ لَمۡ يَكُ مُغَيِّرٗا نِّعۡمَةً أَنۡعَمَهَا عَلَىٰ قَوۡمٍ حَتَّىٰ يُغَيِّرُواْ مَا بِأَنفُسِهِمۡ وَأَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ","aya_text_emlaey":"ذلك بأن الله لم يك مغيرا نعمة أنعمها على قوم حتى يغيروا ما بأنفسهم وأن الله سميع عليم","aya_tafseer":"[53] ذلك الجزاء السيِّئ بأن الله إذا أنعم على قوم نعمة لم يسلبها منهم حتى يغيِّروا حالهم الطيبة إلى حال سيئة، وأن الله سميع لأقوال خلقه، عليم بأحوالهم، فيُجري عليهم ما اقتضاه علمه ومشيئته."},{"id":"1214","jozz":"10","page":"184","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"2","line_end":"4","aya_no":"54","aya_text":"كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِينَ مِن قَبۡلِهِمۡۚ كَذَّبُواْ بِـَٔايَٰتِ رَبِّهِمۡ فَأَهۡلَكۡنَٰهُم بِذُنُوبِهِمۡ وَأَغۡرَقۡنَآ ءَالَ فِرۡعَوۡنَۚ وَكُلّٞ كَانُواْ ظَٰلِمِينَ","aya_text_emlaey":"كدأب آل فرعون والذين من قبلهم كذبوا بآيات ربهم فأهلكناهم بذنوبهم وأغرقنا آل فرعون وكل كانوا ظالمين","aya_tafseer":"[54] شأن هؤلاء الكافرين في ذلك كشأن آل فرعون الذين كذبوا موسى، وشأنِ الذين كذبوا رسلهم من الأمم السابقة فأهلكهم الله بسبب ذنوبهم، وأغرق آل فرعون في البحر، وكل منهم كان فاعلاً ما لم يكن له فِعْلُه من تكذيبهم رسل الله وجحودهم آياته، وإشراكهم في العبادة غيره."},{"id":"1215","jozz":"10","page":"184","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"5","line_end":"5","aya_no":"55","aya_text":"إِنَّ شَرَّ ٱلدَّوَآبِّ عِندَ ٱللَّهِ ٱلَّذِينَ كَفَرُواْ فَهُمۡ لَا يُؤۡمِنُونَ","aya_text_emlaey":"إن شر الدواب عند الله الذين كفروا فهم لا يؤمنون","aya_tafseer":"[55] إن شرَّ ما دبَّ على الأرض عند الله الكفار المصرُّون على الكفر، فهم لا يصدقون رسل الله، ولا يُقرُّون بوحدانيته، ولا يتبعون شرعه."},{"id":"1216","jozz":"10","page":"184","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"6","line_end":"7","aya_no":"56","aya_text":"ٱلَّذِينَ عَٰهَدتَّ مِنۡهُمۡ ثُمَّ يَنقُضُونَ عَهۡدَهُمۡ فِي كُلِّ مَرَّةٖ وَهُمۡ لَا يَتَّقُونَ","aya_text_emlaey":"الذين عاهدت منهم ثم ينقضون عهدهم في كل مرة وهم لا يتقون","aya_tafseer":"[56] مِن أولئك الأشرار اليهودُ الذين دخلوا معك في المعاهدات بأن لا يحاربوك ولا يظاهروا عليك أحداً، ثم ينقضون عهدهم المرة تلو المرة، وهم لا يخافون الله."},{"id":"1217","jozz":"10","page":"184","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"7","line_end":"8","aya_no":"57","aya_text":"فَإِمَّا تَثۡقَفَنَّهُمۡ فِي ٱلۡحَرۡبِ فَشَرِّدۡ بِهِم مَّنۡ خَلۡفَهُمۡ لَعَلَّهُمۡ يَذَّكَّرُونَ","aya_text_emlaey":"فإما تثقفنهم في الحرب فشرد بهم من خلفهم لعلهم يذكرون","aya_tafseer":"[57] فإن واجهت هؤلاء الناقضين للعهود والمواثيق في المعركة، فأنزِلْ بهم من العذاب ما يُدْخل الرعب في قلوب الآخرين، ويشتت جموعهم؛ لعلهم يذَّكرون، فلا يجترئون على مثل الذي أقدم عليه السابقون."},{"id":"1218","jozz":"10","page":"184","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"8","line_end":"9","aya_no":"58","aya_text":"وَإِمَّا تَخَافَنَّ مِن قَوۡمٍ خِيَانَةٗ فَٱنۢبِذۡ إِلَيۡهِمۡ عَلَىٰ سَوَآءٍۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡخَآئِنِينَ","aya_text_emlaey":"وإما تخافن من قوم خيانة فانبذ إليهم على سواء إن الله لا يحب الخائنين","aya_tafseer":"[58] وإن خفت -أيها الرسول- مِن قومٍ خيانة ظهرت بوادرها فألق إليهم عهدهم؛ كي يكون الطرفان مستويين في العلم بأنه لا عهد بعد اليوم. إن الله لا يحب الخائنين في عهودهم الناقضين للعهد والميثاق."},{"id":"1219","jozz":"10","page":"184","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"10","line_end":"10","aya_no":"59","aya_text":"وَلَا يَحۡسَبَنَّ ٱلَّذِينَ كَفَرُواْ سَبَقُوٓاْۚ إِنَّهُمۡ لَا يُعۡجِزُونَ","aya_text_emlaey":"ولا يحسبن الذين كفروا سبقوا إنهم لا يعجزون","aya_tafseer":"[59] ولا يظننَّ الذين جحدوا آيات الله أنهم فاتوا ونجَوْا، وأن الله لا يقدر عليهم، إنهم لن يُفْلِتوا من عذاب الله."},{"id":"1220","jozz":"10","page":"184","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"11","line_end":"14","aya_no":"60","aya_text":"وَأَعِدُّواْ لَهُم مَّا ٱسۡتَطَعۡتُم مِّن قُوَّةٖ وَمِن رِّبَاطِ ٱلۡخَيۡلِ تُرۡهِبُونَ بِهِۦ عَدُوَّ ٱللَّهِ وَعَدُوَّكُمۡ وَءَاخَرِينَ مِن دُونِهِمۡ لَا تَعۡلَمُونَهُمُ ٱللَّهُ يَعۡلَمُهُمۡۚ وَمَا تُنفِقُواْ مِن شَيۡءٖ فِي سَبِيلِ ٱللَّهِ يُوَفَّ إِلَيۡكُمۡ وَأَنتُمۡ لَا تُظۡلَمُونَ","aya_text_emlaey":"وأعدوا لهم ما استطعتم من قوة ومن رباط الخيل ترهبون به عدو الله وعدوكم وآخرين من دونهم لا تعلمونهم الله يعلمهم وما تنفقوا من شيء في سبيل الله يوف إليكم وأنتم لا تظلمون","aya_tafseer":"[60] وأعدُّوا -يا معشر المسلمين -لمواجهة أعدائكم كل ما تقدرون عليه مِن عُدَدٍ وعُدَّة، لتُدْخلوا بذلك الرهبةَ في قلوب أعداء الله وأعدائكم المتربصين بكم، وتخيفوا آخرين لا تظهر لكم عداوتهم الآن، لكن الله يعلمهم ويعلم ما يضمرونه. وما تبذلوا من مال وغيره في سبيل الله قليلاً أو كثيراً يخلفه الله عليكم في الدنيا، ويدخر لكم ثوابه إلى يوم القيامة، وأنتم لا تُنقَصون من أجر ذلك شيئاً."},{"id":"1221","jozz":"10","page":"184","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"14","line_end":"15","aya_no":"61","aya_text":"۞ وَإِن جَنَحُواْ لِلسَّلۡمِ فَٱجۡنَحۡ لَهَا وَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ","aya_text_emlaey":"وإن جنحوا للسلم فاجنح لها وتوكل على الله إنه هو السميع العليم","aya_tafseer":"[61] وإن مالوا إلى ترك الحرب ورغبوا في مسالمتكم فمِلْ إلى ذلك -أيها النبي- وفَوِّضْ أمرك إلى الله، وثق به. إنه هو السميع لأقوالهم، العليم بنيَّاتهم."},{"id":"1222","jozz":"10","page":"185","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"1","line_end":"2","aya_no":"62","aya_text":"وَإِن يُرِيدُوٓاْ أَن يَخۡدَعُوكَ فَإِنَّ حَسۡبَكَ ٱللَّهُۚ هُوَ ٱلَّذِيٓ أَيَّدَكَ بِنَصۡرِهِۦ وَبِٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"وإن يريدوا أن يخدعوك فإن حسبك الله هو الذي أيدك بنصره وبالمؤمنين","aya_tafseer":"[62] وإن أراد الذين عاهدوك المكرَ بك فإن الله سيكفيك خداعهم؛ إنه هو الذي أنزل عليك نصره وقوَّاك بالمؤمنين من المهاجرين والأنصار"},{"id":"1223","jozz":"10","page":"185","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"2","line_end":"4","aya_no":"63","aya_text":"وَأَلَّفَ بَيۡنَ قُلُوبِهِمۡۚ لَوۡ أَنفَقۡتَ مَا فِي ٱلۡأَرۡضِ جَمِيعٗا مَّآ أَلَّفۡتَ بَيۡنَ قُلُوبِهِمۡ وَلَٰكِنَّ ٱللَّهَ أَلَّفَ بَيۡنَهُمۡۚ إِنَّهُۥ عَزِيزٌ حَكِيمٞ","aya_text_emlaey":"وألف بين قلوبهم لو أنفقت ما في الأرض جميعا ما ألفت بين قلوبهم ولكن الله ألف بينهم إنه عزيز حكيم","aya_tafseer":"[63] وجَمَع بين قلوبهم بعد التفرق، لو أنفقت مال الدنيا على جمع قلوبهم ما استطعت إلى ذلك سبيلاً، ولكن الله جمع بينها على الإيمان فأصبحوا إخواناً متحابين، إنه عزيز في مُلْكه، حكيم في أمره وتدبيره."},{"id":"1224","jozz":"10","page":"185","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"4","line_end":"5","aya_no":"64","aya_text":"يَٰٓأَيُّهَا ٱلنَّبِيُّ حَسۡبُكَ ٱللَّهُ وَمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِينَ","aya_text_emlaey":"ياأيها النبي حسبك الله ومن اتبعك من المؤمنين","aya_tafseer":"[64] يا أيها النبي إن الله كافيك، وكافي الذين معك من المؤمنين شرَّ أعدائكم."},{"id":"1225","jozz":"10","page":"185","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"5","line_end":"8","aya_no":"65","aya_text":"يَٰٓأَيُّهَا ٱلنَّبِيُّ حَرِّضِ ٱلۡمُؤۡمِنِينَ عَلَى ٱلۡقِتَالِۚ إِن يَكُن مِّنكُمۡ عِشۡرُونَ صَٰبِرُونَ يَغۡلِبُواْ مِاْئَتَيۡنِۚ وَإِن يَكُن مِّنكُم مِّاْئَةٞ يَغۡلِبُوٓاْ أَلۡفٗا مِّنَ ٱلَّذِينَ كَفَرُواْ بِأَنَّهُمۡ قَوۡمٞ لَّا يَفۡقَهُونَ","aya_text_emlaey":"ياأيها النبي حرض المؤمنين على القتال إن يكن منكم عشرون صابرون يغلبوا مائتين وإن يكن منكم مائة يغلبوا ألفا من الذين كفروا بأنهم قوم لا يفقهون","aya_tafseer":"[65] يا أيها النبي حُثَّ المؤمنين بك على القتال، إن يكن منكم عشرون صابرون عند لقاء العدو يغلبوا مائتين منهم، وإن يكن منكم مائة مجاهدة صابرة يغلبوا ألفاً من الكفار؛ لأنهم قوم لا عِلْم ولا فَهْم عندهم لِمَا أعدَّ الله للمجاهدين في سبيله، فهم يقاتلون من أجل العلو في الأرض والفساد فيها."},{"id":"1226","jozz":"10","page":"185","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"8","line_end":"11","aya_no":"66","aya_text":"ٱلۡـَٰٔنَ خَفَّفَ ٱللَّهُ عَنكُمۡ وَعَلِمَ أَنَّ فِيكُمۡ ضَعۡفٗاۚ فَإِن يَكُن مِّنكُم مِّاْئَةٞ صَابِرَةٞ يَغۡلِبُواْ مِاْئَتَيۡنِۚ وَإِن يَكُن مِّنكُمۡ أَلۡفٞ يَغۡلِبُوٓاْ أَلۡفَيۡنِ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ","aya_text_emlaey":"الآن خفف الله عنكم وعلم أن فيكم ضعفا فإن يكن منكم مائة صابرة يغلبوا مائتين وإن يكن منكم ألف يغلبوا ألفين بإذن الله والله مع الصابرين","aya_tafseer":"[66] الآن خفف الله عنكم أيها المؤمنون لما فيكم من الضعف، فإن يكن منكم مائة صابرة يغلبوا مائتين من الكافرين، وإن يكن منكم ألف يغلبوا ألفين منهم بإذن الله تعالى. والله مع الصابرين بتأييده ونصره."},{"id":"1227","jozz":"10","page":"185","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"11","line_end":"13","aya_no":"67","aya_text":"مَا كَانَ لِنَبِيٍّ أَن يَكُونَ لَهُۥٓ أَسۡرَىٰ حَتَّىٰ يُثۡخِنَ فِي ٱلۡأَرۡضِۚ تُرِيدُونَ عَرَضَ ٱلدُّنۡيَا وَٱللَّهُ يُرِيدُ ٱلۡأٓخِرَةَۗ وَٱللَّهُ عَزِيزٌ حَكِيمٞ","aya_text_emlaey":"ما كان لنبي أن يكون له أسرى حتى يثخن في الأرض تريدون عرض الدنيا والله يريد الآخرة والله عزيز حكيم","aya_tafseer":"[67] لا ينبغي لنبي أن يكون له أسرى مِن أعدائه حتى يبالغ في القتل؛ لإدخال الرعب في قلوبهم ويوطد دعائم الدين، تريدون -يا معشر المسلمين- بأخذكم الفداء من أسرى «بدر» متاع الدنيا، والله يريد إظهار دينه الذي به تدرك الآخرة. والله عزيز لا يُقْهَر، حكيم في شرعه."},{"id":"1228","jozz":"10","page":"185","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"13","line_end":"14","aya_no":"68","aya_text":"لَّوۡلَا كِتَٰبٞ مِّنَ ٱللَّهِ سَبَقَ لَمَسَّكُمۡ فِيمَآ أَخَذۡتُمۡ عَذَابٌ عَظِيمٞ","aya_text_emlaey":"لولا كتاب من الله سبق لمسكم فيما أخذتم عذاب عظيم","aya_tafseer":"[68] لولا كتاب من الله سبق به القضاء والقدر بإباحة الغنيمة وفداء الأسرى لهذه الأمة، لنالكم عذاب عظيم بسبب أخْذكم الغنيمة والفداء قبل أن ينزل بشأنهما تشريع."},{"id":"1229","jozz":"10","page":"185","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"14","line_end":"15","aya_no":"69","aya_text":"فَكُلُواْ مِمَّا غَنِمۡتُمۡ حَلَٰلٗا طَيِّبٗاۚ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","aya_text_emlaey":"فكلوا مما غنمتم حلالا طيبا واتقوا الله إن الله غفور رحيم","aya_tafseer":"[69] فكلوا من الغنائم وفداء الأسرى فهو حلال طيب، وحافظوا على أحكام دين الله وتشريعاته. إن الله غفور لعباده، رحيم بهم."},{"id":"1230","jozz":"10","page":"186","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"1","line_end":"3","aya_no":"70","aya_text":"يَٰٓأَيُّهَا ٱلنَّبِيُّ قُل لِّمَن فِيٓ أَيۡدِيكُم مِّنَ ٱلۡأَسۡرَىٰٓ إِن يَعۡلَمِ ٱللَّهُ فِي قُلُوبِكُمۡ خَيۡرٗا يُؤۡتِكُمۡ خَيۡرٗا مِّمَّآ أُخِذَ مِنكُمۡ وَيَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ","aya_text_emlaey":"ياأيها النبي قل لمن في أيديكم من الأسرى إن يعلم الله في قلوبكم خيرا يؤتكم خيرا مما أخذ منكم ويغفر لكم والله غفور رحيم","aya_tafseer":"[70] يا أيها النبي قل لمن أسرتموهم في «بدر»: لا تأسوا على الفداء الذي أُخذ منكم، إن يعلم الله تعالى في قلوبكم خيراً يؤتكم خيراً مما أُخذ منكم من المال، بأن يُيَسِّر لكم من فضله خيراً كثيراً -وقد أنجز الله وعده للعباس رضي الله عنه وغيره-، ويغفر لكم ذنوبكم. والله سبحانه غفور لذنوب عباده إذا تابوا، رحيم بهم."},{"id":"1231","jozz":"10","page":"186","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"3","line_end":"4","aya_no":"71","aya_text":"وَإِن يُرِيدُواْ خِيَانَتَكَ فَقَدۡ خَانُواْ ٱللَّهَ مِن قَبۡلُ فَأَمۡكَنَ مِنۡهُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٌ","aya_text_emlaey":"وإن يريدوا خيانتك فقد خانوا الله من قبل فأمكن منهم والله عليم حكيم","aya_tafseer":"[71] وإن يرد الذين أَطْلَقْتَ سراحهم -أيها النبي- من الأسرى الغدر بك مرة أخرى فلا تَيْئسْ، فقد خانوا الله من قبل وحاربوك، فنصرك الله عليهم. والله عليم بما تنطوي عليه الصدور، حكيم في تدبير شؤون عباده."},{"id":"1232","jozz":"10","page":"186","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"4","line_end":"9","aya_no":"72","aya_text":"إِنَّ ٱلَّذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَواْ وَّنَصَرُوٓاْ أُوْلَٰٓئِكَ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ وَٱلَّذِينَ ءَامَنُواْ وَلَمۡ يُهَاجِرُواْ مَا لَكُم مِّن وَلَٰيَتِهِم مِّن شَيۡءٍ حَتَّىٰ يُهَاجِرُواْۚ وَإِنِ ٱسۡتَنصَرُوكُمۡ فِي ٱلدِّينِ فَعَلَيۡكُمُ ٱلنَّصۡرُ إِلَّا عَلَىٰ قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٞۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرٞ","aya_text_emlaey":"إن الذين آمنوا وهاجروا وجاهدوا بأموالهم وأنفسهم في سبيل الله والذين آووا ونصروا أولئك بعضهم أولياء بعض والذين آمنوا ولم يهاجروا ما لكم من ولايتهم من شيء حتى يهاجروا وإن استنصروكم في الدين فعليكم النصر إلا على قوم بينكم وبينهم ميثاق والله بما تعملون بصير","aya_tafseer":"[72] إن الذين صَدَّقوا الله ورسوله وعملوا بشرعه، وهاجروا إلى دار الإسلام، أو بلد يتمكنون فيه من عبادة ربهم، وجاهدوا في سبيل الله بالمال والنفس، والذين أنزلوا المهاجرين في دورهم، وواسوهم بأموالهم، ونصروا دين الله، أولئك بعضهم نصراء بعض. أما الذين آمنوا ولم يهاجروا من دار الكفر فلستم مكلَّفين بحمايتهم ونصرتهم حتى يهاجروا، وإن وقع عليهم ظلم من الكفار فطلبوا نصرتكم فاستجيبوا لهم، إلا على قوم بينكم وبينهم عهد مؤكد لم ينقضوه. والله بصير بأعمالكم، يجزي كُلّاً على قدر نيته وعمله."},{"id":"1233","jozz":"10","page":"186","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"9","line_end":"11","aya_no":"73","aya_text":"وَٱلَّذِينَ كَفَرُواْ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٍۚ إِلَّا تَفۡعَلُوهُ تَكُن فِتۡنَةٞ فِي ٱلۡأَرۡضِ وَفَسَادٞ كَبِيرٞ","aya_text_emlaey":"والذين كفروا بعضهم أولياء بعض إلا تفعلوه تكن فتنة في الأرض وفساد كبير","aya_tafseer":"[73] والذين كفروا بعضهم نصراء بعض، وإن لم تكونوا -أيها المؤمنون- نصراء بعض تكن في الأرض فتنة للمؤمنين عن دين الله، وفساد عريض بالصد عن سبيل الله وتقوية دعائم الكفر."},{"id":"1234","jozz":"10","page":"186","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"11","line_end":"13","aya_no":"74","aya_text":"وَٱلَّذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ وَٱلَّذِينَ ءَاوَواْ وَّنَصَرُوٓاْ أُوْلَٰٓئِكَ هُمُ ٱلۡمُؤۡمِنُونَ حَقّٗاۚ لَّهُم مَّغۡفِرَةٞ وَرِزۡقٞ كَرِيمٞ","aya_text_emlaey":"والذين آمنوا وهاجروا وجاهدوا في سبيل الله والذين آووا ونصروا أولئك هم المؤمنون حقا لهم مغفرة ورزق كريم","aya_tafseer":"[74] والذين آمنوا بالله ورسوله، وتركوا ديارهم قاصدين دار الإسلام، أو بلداً يتمكنون فيه من عبادة ربهم، وجاهدوا لإعلاء كلمة الله، والذين نصروا إخوانهم المهاجرين وآوَوْهم وواسَوْهم بالمال والتأييد، أولئك هم المؤمنون الصادقون حقّاً، لهم مغفرة لذنوبهم، ورزق كريم واسع في جنات النعيم."},{"id":"1235","jozz":"10","page":"186","sura_no":"8","sura_name_en":"Al-Anfāl","sura_name_ar":"الأنفَال ","line_start":"13","line_end":"15","aya_no":"75","aya_text":"وَٱلَّذِينَ ءَامَنُواْ مِنۢ بَعۡدُ وَهَاجَرُواْ وَجَٰهَدُواْ مَعَكُمۡ فَأُوْلَٰٓئِكَ مِنكُمۡۚ وَأُوْلُواْ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضٖ فِي كِتَٰبِ ٱللَّهِۚ إِنَّ ٱللَّهَ بِكُلِّ شَيۡءٍ عَلِيمُۢ","aya_text_emlaey":"والذين آمنوا من بعد وهاجروا وجاهدوا معكم فأولئك منكم وأولو الأرحام بعضهم أولى ببعض في كتاب الله إن الله بكل شيء عليم","aya_tafseer":"[75] والذين آمنوا مِن بعد هؤلاء المهاجرين والأنصار، وهاجروا وجاهدوا معكم في سبيل الله، فأولئك منكم -أيها المؤمنون- لهم ما لكم وعليهم ما عليكم، وأولو القرابة بعضهم أولى ببعض في التوارث في حكم الله من عامة المسلمين. إن الله بكل شيء عليم، يعلم ما يصلح عباده مِن توريث بعضهم من بعض في القرابة والنسب دون التوارث بالحِلْف، وغير ذلك مما كان في أول الإسلام."}]
